const A='/assets/';
const eventURL='/events/sohaibboxing.com/';
const official='https://sohaibboxing.com';
const main=document.querySelector('main');
const path=location.pathname.replace(/\/$/,'')||'/';
const button=(text,href,outline=false)=>`<a class="button ${outline?'outline':''}" href="${href}">${text}</a>`;
const countdown=()=>`<div class="countdown" aria-label="Time until doors open on 24 October 2026 at 7pm UK time"><div><b data-time="days">00</b><small>DAYS</small></div><span class="colon">:</span><div><b data-time="hours">00</b><small>HOURS</small></div><span class="colon">:</span><div><b data-time="minutes">00</b><small>MINS</small></div><span class="colon">:</span><div><b data-time="seconds">00</b><small>SECS</small></div></div>`;
const fight=()=>`<section class="section" id="next-fight"><div class="fight-grid"><a class="poster-wrap" href="${eventURL}" aria-label="View the Glasgow fight night"><img src="${A}b075c7a3-0007-49c9-ab43-9ce1fa01ba54.jpeg" alt="Official Kynoch Boxing Promotions event poster" loading="lazy"></a><div><span class="eyebrow">Next up · 24 October 2026</span><h2 class="fight-title">Glasgow.<br><em>Under the lights.</em></h2><p>An amazing night of professional boxing.<br>Featuring Sohaib Mohammed. Promoted by Kynoch Boxing Promotions.</p><div class="event-meta"><div><small>When</small><strong>Saturday 24 October · Doors 19:00</strong></div><div><small>Where</small><strong>Crowne Plaza Glasgow</strong></div></div>${countdown()}<div class="fight-actions">${button('Find your seat',eventURL)}<p>Tickets from <strong>£65</strong></p></div></div></div></section>`;
const hero=()=>`<section class="hero-scroll"><div class="hero"><img class="hero-photo" src="${A}hero-ring-portrait.jpg" alt="Sohaib Mohammed standing in the ring under the arena lights" fetchpriority="high"><img class="hero-action" src="${A}action-punch.jpg" alt="" aria-hidden="true"><div class="hero-shade"></div><div class="hero-topline"><span>Professional boxer · United Kingdom</span><span>Dedication. Discipline. Belief.</span></div><div class="hero-copy"><span class="eyebrow">Inside the ropes</span><h1>Sohaib<span>Mohammed</span></h1><p class="hero-tagline">Every round. Everything.</p>${button('Be there · 24 October',eventURL)}</div><span class="hero-side">The work continues / Sohaib Mohammed</span><div class="hero-bottom"><a class="scroll-cue" href="#next-fight"><i></i>Scroll to<br>step inside</a><a class="hero-event" href="${eventURL}"><span>NEXT FIGHT NIGHT</span><strong>24.10.26 / Glasgow</strong><small>Crowne Plaza · Kynoch Boxing Promotions</small></a></div></div></section><div class="marquee" aria-hidden="true"><div>${Array(4).fill('SOHAIB MOHAMMED <span>✦</span> EVERY ROUND. EVERYTHING. <span>✦</span> GLASGOW · 24 OCTOBER <span>✦</span>').join('')}</div></div>`;
const photos=[['action-punch.jpg','Fight night','Sohaib Mohammed lands a right hand during a bout','Fight night'],['action-cross.jpg','Under the lights','Sohaib Mohammed throwing a straight shot','Fight night'],['ring-walk.jpg','Ring walk','Sohaib Mohammed acknowledging the crowd in the ring','Fight night'],['action-guard.jpg','Mid-round','Sohaib Mohammed setting his guard mid-round','Fight night'],['pads-work.jpg','Camp','Sohaib Mohammed working the pads with his coach','Training'],['hand-wraps.jpg','Wraps on',"A coach wrapping Sohaib Mohammed’s hands before a fight",'Training'],['portrait-spotlight.jpg','Spotlight','Portrait of Sohaib Mohammed under the arena lights','Portraits'],['trunks-pose.jpg','Before the first bell','Sohaib Mohammed in the ring before a bout','Portraits'],['hero-ring-portrait.jpg','In the ring','Sohaib Mohammed standing in the ring under arena lights','Portraits']];
const photoCard=(p,i)=>`<button class="photo-card" data-photo="${i}" data-category="${p[3]}" aria-label="View ${p[1]} photograph"><div><img src="${A+p[0]}" alt="${p[2]}" loading="lazy"><span class="photo-open">View photograph +</span></div><span class="photo-caption"><strong>${p[1]}</strong><small>${p[3]}</small></span></button>`;
const bio=`<p>Sohaib Mohammed is a professional boxer with experience competing at fight nights, tournaments and combat-sport events across the UK, including appearances in Scotland.</p><p>Known for his dedication, discipline and competitive mindset, Sohaib has stepped into the ring at a variety of events, building his experience through competitive bouts and successful performances.</p><p>His journey has taken him through demanding training camps and high-pressure fight nights, representing his team and continuing to develop his professional career with every appearance.</p><p>With victories already part of his journey, Sohaib’s focus remains firmly on what comes next — bigger events, tougher competition and continuing to establish his name within the UK boxing scene.</p>`;
const tickets=[{name:'Boxing Only',price:65,desc:'Standard admission to the boxing.',detail:'Be there for every round.'},{name:'Dinner Guest',price:100,desc:'The dinner guest ticket option.',detail:'Contact the team to confirm hospitality and seating details.'},{name:'Inner Row',price:150,desc:'Premium inner row seating.',detail:'A closer view of the action.'},{name:'VIP Ringside',price:250,desc:'The complete ringside experience.',detail:'Welcome drinks, a three-course meal, ringside table position and a table drinks package: a bottle of vodka, 24 beers and mixers. Non-alcoholic arrangements available.'}];
const ticketCards=()=>`<div class="ticket-grid">${tickets.map((t,i)=>`<article class="ticket-card ${i===3?'vip':''}"><span class="ticket-label">${i===3?'The premium experience':'24 October · Glasgow'}</span><h3>${t.name}</h3><div class="ticket-price">£${t.price}<small>/ person</small></div><p>${t.desc}</p><p class="ticket-detail">${t.detail}</p><a class="ticket-select" href="${eventURL}?tier=${i}#booking">Choose ${t.name}</a></article>`).join('')}</div>`;
const ticketSection=()=>`<section class="section tickets-section"><div class="section-head"><div><span class="eyebrow">Your night. Your seat.</span><h2>Be part of it.</h2></div><p>From the first bell to the final round.<br>Four ways to experience fight night.</p></div>${ticketCards()}<p class="ticket-note">Prices in GBP. Non-refundable and non-transferable for this event. Confirm current availability on the official booking page.</p></section>`;
const story=()=>`<section class="section story-section"><div class="story-image"><img src="${A}trunks-pose.jpg" alt="Sohaib Mohammed before the first bell" loading="lazy"><span>Before the first bell / Sohaib Mohammed</span></div><div class="story-copy"><span class="eyebrow">The man behind the gloves</span><h2>Built in camp.<br><em>Proven in<br>the ring.</em></h2><p>Dedication, discipline and a competitive mindset. From demanding training camps to fight nights across the UK, Sohaib’s focus is on what comes next.</p><a class="text-link" href="/about/">Meet Sohaib</a></div></section>`;
const galleryPreview=()=>`<section class="section gallery-preview"><div class="section-head"><div><span class="eyebrow">A closer look</span><h2>Inside the ropes.</h2></div><div><p>The work. The wait. The moment.</p><a class="text-link" href="/gallery/">Explore the gallery</a></div></div><div class="gallery-teaser">${[0,5,2].map(i=>photoCard(photos[i],i)).join('')}</div></section>`;
const partnerships=()=>`<section class="section partnership-section"><div class="section-head"><div><span class="eyebrow">In his corner</span><h2>More than<br>fight night.</h2></div><p>Partnerships that go beyond the ropes.<br>Work with Sohaib and his team.</p></div><div class="partnership-grid"><a href="/become-a-sponsor/"><span class="eyebrow">Sponsorship</span><h3>Back the journey.</h3><p>Ringside branding, shorts and poster placement, hospitality and fight-night exposure.</p><span class="text-link">Become a sponsor</span></a><a href="/invite/"><span class="eyebrow">Appearances</span><h3>Bring the story to you.</h3><p>Charity nights, gym openings, school visits, media work and corporate events across the UK.</p><span class="text-link">Invite Sohaib</span></a></div></section>`;
const contactStrip=()=>`<section class="contact-strip"><span class="eyebrow">Tickets. Tables. Enquiries.</span><h2>Let’s talk<br><em>fight night.</em></h2><div><a href="tel:+447805162717">+44 7805 162717</a><p>For group bookings, tables and accessibility requirements.</p><a class="text-link" href="/contact/">Contact the team</a></div></section>`;
const pageHead=(label,title,copy)=>`<section class="page-head"><span class="eyebrow">${label}</span><h1>${title}</h1>${copy?`<p>${copy}</p>`:''}</section>`;
const faqs=[['How do I buy tickets?','Choose a published event, select your ticket categories and pay securely by card on the official website. Your tickets are emailed to you straight after payment.'],['Do I need an account to buy tickets?','No. You can buy as a guest. You only need to provide your name, email address and telephone number.'],['How will I receive my tickets?','Each ticket is issued individually with its own QR code and sent to the email address used at checkout. If you buy four tickets you receive four separate QR codes.'],['What if I do not receive my confirmation email?','Please check your spam folder first. If it has not arrived, contact the team with your order reference and they will resend it.'],['Are tickets refundable?','Refund eligibility is set per event and per ticket category, and is shown before you pay. The 24 October event currently lists tickets as non-refundable. Read the official ticket and refund policy before booking.'],['Can I transfer my ticket to somebody else?','Transfers are only available where the event organiser has enabled them. This is shown on the event page. The 24 October event currently lists tickets as non-transferable.'],['Is there a minimum age?','Age restrictions vary by event and by ticket category. Any restriction is displayed on the official event page and on your ticket.'],['What do I need to bring on the night?','Bring your QR ticket, either printed or on your phone, along with any identification required by the venue.']];
const faqList=()=>`<div class="faq-list">${faqs.map(([q,a])=>`<details><summary>${q}<span>+</span></summary><p>${a}</p></details>`).join('')}</div>`;
const booking=()=>`<section class="section booking-section" id="booking"><div><span class="eyebrow">24 October 2026 · Crowne Plaza Glasgow</span><h2>Your ringside<br>starts here.</h2><p>Choose an experience to see your ticket total, then book securely with Sohaib’s team.</p><div class="booking-assurance"><h3>Direct from the team.</h3><p>Official booking offers secure card payment in pounds and individual QR tickets by email. For dinner tables, ringside blocks and party bookings, call the team.</p><a class="text-link" href="tel:+447805162717">+44 7805 162717</a></div></div><div class="booking-box"><label for="tier">Your experience</label><select id="tier">${tickets.map((t,i)=>`<option value="${i}">${t.name} — £${t.price}</option>`).join('')}</select><p id="tier-description"></p><label for="quantity">Number of tickets</label><div class="quantity-control"><button id="minus" aria-label="Decrease ticket quantity">−</button><input id="quantity" type="number" min="1" max="10" value="1" inputmode="numeric"><button id="plus" aria-label="Increase ticket quantity">+</button></div><div class="total"><span>Ticket total</span><strong id="total" aria-live="polite">£65</strong></div><p class="booking-policy">Non-refundable · Non-transferable</p>${button('Continue to official booking',official+'/events/sohaibboxing.com')}<small>Select your tickets again on the official site. Availability and final pricing are confirmed there.</small></div></section>`;
let title='Sohaib Mohammed — Every Round. Everything.';
if(path==='/')main.innerHTML=hero()+fight()+ticketSection()+story()+galleryPreview()+partnerships()+contactStrip();
else if(path==='/events'||path==='/events/sohaibboxing.com'){title='Fight Nights & Tickets | Sohaib Mohammed';main.innerHTML=pageHead('Fight nights',path==='/events'?'The next chapter.':'A night to remember.','Professional boxing. Glasgow. Be there for every round.')+fight()+ticketSection()+booking()+`<section class="section compact"><div class="section-head"><h2>Know before<br>you go.</h2><p>Doors open at 19:00 UK time.<br>Saturday 24 October 2026.</p></div>${faqList()}</section>`;}
else if(path==='/about'){title='The Fighter | Sohaib Mohammed';main.innerHTML=pageHead('The fighter','Sohaib<br><em>Mohammed.</em>','Professional boxer. Dedication, discipline and a competitive mindset.')+`<section class="section profile"><div><img src="${A}portrait-spotlight.jpg" alt="Sohaib Mohammed under the arena lights"><span class="image-note">Under the lights / Sohaib Mohammed</span></div><article><span class="eyebrow">The story so far</span><h2>The work<br>continues.</h2>${bio}${button('See the next fight',eventURL)}</article></section><section class="section camp"><div class="section-head"><div><span class="eyebrow">Before the spotlight</span><h2>It starts here.</h2></div><p>Demanding camps. The final preparations.<br>Every appearance begins with the work.</p></div><div class="camp-grid">${[4,5].map(i=>photoCard(photos[i],i)).join('')}</div></section>`+partnerships();}
else if(path==='/gallery'){title='Inside the Ropes — Gallery | Sohaib Mohammed';main.innerHTML=pageHead('The photographic journal','Inside<br><em>the ropes.</em>','Behind the scenes, in the changing room and under the lights.')+`<section class="section gallery-full"><div class="gallery-tools"><div class="filters" aria-label="Filter photographs">${['All photographs','Fight night','Training','Portraits'].map((f,i)=>`<button data-filter="${f}" aria-pressed="${i===0}">${f}</button>`).join('')}</div><span id="photo-count">9 photographs</span></div><div class="photo-grid">${photos.map(photoCard).join('')}</div></section>`+contactStrip();}
else if(path==='/work-with-me'){title='Partnerships | Sohaib Mohammed';main.innerHTML=pageHead('Partnerships','Be in<br><em>his corner.</em>','Sponsorship, appearances and media opportunities with Sohaib Mohammed.')+`<div class="wide-image"><img src="${A}ring-walk.jpg" alt="Sohaib acknowledging the crowd" loading="eager"></div>`+partnerships()+`<section class="section press"><span class="eyebrow">Media & press</span><h2>Tell the story.</h2><p>Interviews, photography and content requests. Send the details and the team will respond.</p>${button('Contact the team','/contact/')}</section>`;}
else if(['/become-a-sponsor','/invite','/contact'].includes(path)){const sponsor=path==='/become-a-sponsor',invite=path==='/invite';title=(sponsor?'Become a Sponsor':invite?'Invite Sohaib':'Contact the Team')+' | Sohaib Mohammed';main.innerHTML=pageHead(sponsor?'Sponsorship':invite?'Appearances':'Get in touch',sponsor?'Back the<br><em>journey.</em>':invite?'Make it<br><em>an occasion.</em>':'Let’s<br><em>talk.</em>',sponsor?'Put your business in Sohaib’s corner.':invite?'Charity nights, gym openings, school visits and corporate events.':'Questions about tickets, sponsorship or appearances? Speak to the team.')+`<section class="section enquiry"><div class="enquiry-image"><img src="${A+(sponsor?'trunks-pose.jpg':invite?'ring-walk.jpg':'action-guard.jpg')}" alt="Sohaib Mohammed ${sponsor?'before the first bell':invite?'acknowledging the crowd':'mid-round in the ring'}"></div><article><span class="eyebrow">${sponsor?'A partnership with purpose':invite?'Share your plans':'Tickets & enquiries'}</span><h2>${sponsor?'Your brand.<br>His corner.':invite?'An appearance<br>to remember.':'Straight from<br>the team.'}</h2><p>${sponsor?'Partner with a professional fight night: ring branding, shorts and poster placement, hospitality and matchday exposure. Tell the team about your business and the partnership you have in mind. Nothing is confirmed until you have spoken.':invite?'Share the details of your event and the team will come back to you with availability. Include your proposed date, venue, location, what you would like Sohaib to do, and any fee, travel or accommodation arrangements.':'Call for tables, group bookings, accessibility requirements and anything urgent on fight night. Enquiries are answered as quickly as possible, usually within a few working days.'}</p><div class="enquiry-call"><small>Telephone</small><a href="tel:+447805162717">+44 7805 162717</a></div>${button(sponsor?'Open sponsorship enquiry':invite?'Open invitation form':'Open contact form',official+path)}<p class="fineprint">Continue to the team’s official enquiry form.</p>${sponsor?'<p class="fineprint">Have your business details, website, preferred sponsorship type, budget range and event of interest ready.</p>':''}</article></section>`+contactStrip();}
else if(path==='/faq'){title='Frequently Asked Questions | Sohaib Mohammed';main.innerHTML=pageHead('The essentials','Good to know.','Everything you need before fight night.')+`<section class="section compact">${faqList()}</section>`+contactStrip();}
else if(path==='/my-tickets'){title='My Tickets | Sohaib Mohammed';main.innerHTML=pageHead('Ticket office','You’re on<br><em>the list.</em>','View, download and present your official tickets.')+`<section class="section ticket-office"><div><h2>Your night.<br>Your ticket.</h2><p>Use your order reference and the secure code from your confirmation link to access your tickets on the official website.</p><p>Your secure code keeps your tickets private. If you cannot find it, use the link in your confirmation or contact the team for help.</p>${button('Find my official tickets',official+'/my-tickets')}<a class="text-link" href="/contact/">Get ticket support</a></div><img src="${A}hand-wraps.jpg" alt="Final preparations before fight night"></section>`;}
else{main.innerHTML=pageHead('Page not found','Back to<br>the ring.','This page is not available.')+`<section class="section">${button('Return home','/')}</section>`;}
document.title=title;
document.querySelectorAll('nav a').forEach(a=>{if(path===a.getAttribute('href').replace(/\/$/,''))a.setAttribute('aria-current','page')});
document.querySelector('footer').innerHTML=`<div class="footer-grid"><div><a class="brand" href="/"><span class="monogram">SM<span>•</span></span><span>SOHAIB<br>MOHAMMED</span></a><p style="margin-top:20px;font-size:13px">Professional boxer. United Kingdom.</p><a href="tel:+447805162717">+44 7805 162717</a></div><div><h3>Explore</h3><a href="/events/">Fight nights</a><a href="/about/">The fighter</a><a href="/gallery/">Gallery</a><a href="/my-tickets/">My tickets</a><a href="/faq/">FAQs</a></div><div><h3>In his corner</h3><a href="/work-with-me/">Partnerships</a><a href="/become-a-sponsor/">Become a sponsor</a><a href="/invite/">Invite Sohaib</a><a href="/contact/">Contact the team</a></div><div><h3>The details</h3>${[['terms-and-conditions','Terms & conditions'],['privacy-policy','Privacy policy'],['cookie-policy','Cookie policy'],['ticket-and-refund-policy','Ticket & refund policy'],['delivery-and-returns','Delivery & returns']].map(([slug,label])=>`<a href="${official}/legal/${slug}">${label}</a>`).join('')}</div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Sohaib Mohammed</span><span>Prices in GBP · Tickets subject to the official ticket & refund policy</span></div>`;
const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.textContent=open?'Close':'Menu';document.querySelector('nav').classList.toggle('open',open)});
function tick(){const distance=Math.max(0,new Date('2026-10-24T19:00:00+01:00').getTime()-Date.now());const total=Math.floor(distance/1000);const v={days:Math.floor(total/86400),hours:Math.floor(total/3600)%24,minutes:Math.floor(total/60)%60,seconds:total%60};document.querySelectorAll('[data-time]').forEach(e=>e.textContent=String(v[e.dataset.time]).padStart(2,'0'));if(!distance)document.querySelectorAll('.countdown').forEach(e=>e.innerHTML='<p>Fight date reached · Check the official event page for updates.</p>')}tick();setInterval(tick,1000);
let scrollQueued=false;function animateHero(){const s=document.querySelector('.hero-scroll');if(s&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const p=Math.min(1,Math.max(0,-s.getBoundingClientRect().top/(s.offsetHeight-innerHeight)));s.style.setProperty('--hero-scale',1.03+p*.17);s.style.setProperty('--action-opacity',Math.max(0,(p-.35)*1.5));s.style.setProperty('--title-shift',`${-p*90}px`);s.style.setProperty('--title-opacity',1-p*.65)}scrollQueued=false}addEventListener('scroll',()=>{if(!scrollQueued){requestAnimationFrame(animateHero);scrollQueued=true}},{passive:true});animateHero();
const lightbox=document.querySelector('#lightbox');let activePhoto=0;let activeSet=photos.map((_,i)=>i);function showPhoto(i){activePhoto=i;const p=photos[i];lightbox.querySelector('img').src=A+p[0];lightbox.querySelector('img').alt=p[2];lightbox.querySelector('figcaption').textContent=p[1]+' / '+p[3];if(!lightbox.open){lightbox.showModal();document.body.style.overflow='hidden'}}document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>showPhoto(Number(b.dataset.photo))));function stepPhoto(d){showPhoto(activeSet[(activeSet.indexOf(activePhoto)+d+activeSet.length)%activeSet.length])}lightbox.querySelector('.close').addEventListener('click',()=>lightbox.close());lightbox.addEventListener('close',()=>document.body.style.overflow='');lightbox.querySelector('.previous').addEventListener('click',()=>stepPhoto(-1));lightbox.querySelector('.next').addEventListener('click',()=>stepPhoto(1));lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowRight')stepPhoto(1);if(e.key==='ArrowLeft')stepPhoto(-1)});lightbox.addEventListener('click',e=>{if(e.target===lightbox)lightbox.close()});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{const f=b.dataset.filter;activeSet=[];document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',x===b));document.querySelectorAll('.photo-grid [data-photo]').forEach(x=>{x.hidden=f!=='All photographs'&&x.dataset.category!==f;if(!x.hidden)activeSet.push(Number(x.dataset.photo))});document.querySelector('#photo-count').textContent=activeSet.length+' photographs'}));
const tier=document.querySelector('#tier'),qty=document.querySelector('#quantity');if(tier&&qty){const initial=Number(new URLSearchParams(location.search).get('tier')||0);tier.value=String(Math.max(0,Math.min(3,Number.isFinite(initial)?initial:0)));function updateBooking(){qty.value=String(Math.max(1,Math.min(10,Math.floor(Number(qty.value)||1))));const t=tickets[Number(tier.value)];document.querySelector('#total').textContent=new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP',maximumFractionDigits:0}).format(t.price*Number(qty.value));document.querySelector('#tier-description').textContent=t.detail;document.querySelector('#minus').disabled=Number(qty.value)<=1;document.querySelector('#plus').disabled=Number(qty.value)>=10}tier.addEventListener('change',updateBooking);qty.addEventListener('change',updateBooking);document.querySelector('#minus').addEventListener('click',()=>{qty.value=Number(qty.value)-1;updateBooking()});document.querySelector('#plus').addEventListener('click',()=>{qty.value=Number(qty.value)+1;updateBooking()});updateBooking()}
